let zipInputTimer,sceneMode='garden',trayFilter='all';
const decimalMoney=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function costRange(a,b){return Math.abs(a-b)<.5?money(a):money(a)+' – '+money(b)}
function upgradeExperience(){S.costSettings??={mode:'hire',factor:2,siteFactor:1,rate:null,hours:{}};S.costSettings.hours??={}}
function validExperience(v){const c=v.costSettings;if(!c)return true;return ['hire','diy'].includes(c.mode)&&Number.isFinite(c.factor)&&c.factor>=1&&c.factor<=5&&Number.isFinite(c.siteFactor)&&c.siteFactor>=.25&&c.siteFactor<=4&&(!c.rate||/^\d{5}$/.test(c.rate.zip)&&Number.isFinite(c.rate.value)&&c.rate.value>0&&c.rate.value<=500)&&c.hours&&typeof c.hours==='object'&&!Array.isArray(c.hours)&&Object.keys(c.hours).length<=300&&Object.entries(c.hours).every(([key,o])=>key.length<100&&o&&typeof o.signature==='string'&&o.signature.length<50000&&Number.isFinite(o.hours)&&o.hours>=0&&o.hours<=10000)}
function wageMarket(){const state=S.location?.zip===S.zip?S.location.state:null,data=Object.hasOwn(REGIONAL_WAGES.states,state)?REGIONAL_WAGES.states[state]:null;return {state:state||null,name:data?data.name:'United States',data:data||REGIONAL_WAGES.national,level:data?'State-level wage benchmark':'National wage benchmark; add or resolve a ZIP',zip:S.zip}}
function defaultLabor(row){const quantity=parseFloat(row.qty)||0;if(row.key.startsWith('ground:')||row.key.startsWith('path:')){const material=MATERIALS[row.key.split(':')[1]],category=material?.category;return {hours:quantity*({pavers:.14,stone:.14,concrete:.14,gravel:.04,decking:.16,green:.025}[category]||.14),trade:category==='green'?'garden':'build',basis:'Template hours per sq ft; editable planning assumption'}}if(row.key.startsWith('object:')){const c=CATALOG[row.key.slice(7)];if(c?.type==='plant')return {hours:quantity*(c.group==='trees'?2:c.group==='shrubs'?.6:c.group==='edible'?.8:.35),trade:'garden',basis:'Template hours per plant symbol; editable planning assumption'};if(c?.type==='furniture')return {hours:quantity*.25,trade:'build',basis:'Template assembly / placement hours; heavy handling excluded'}}return {hours:null,trade:row.key.startsWith('utility:')?'build':'garden',basis:'Specialist installation needs a quote or your own hours'}}
function withLabor(e){const c=S.costSettings,market=wageMarket(),packageRow=e.rows.find(r=>r.key==='extra:labour'),packageFound=!!packageRow?.quote,packageConflict=packageFound&&e.rows.some(r=>r.key!=='extra:labour'&&r.quote?.scope==='installed'),packageQuoted=packageFound&&!packageConflict;if(packageConflict){const omitted=packageRow.amount||0;e={...e,subtotal:e.subtotal-omitted,localTotal:e.localTotal-omitted,unknown:e.unknown+1};e.reserve=e.subtotal*S.reserve/100;e.total=e.subtotal+e.reserve;packageRow.amount=null}let low=0,high=0,knownHours=0,unknown=0;const laborRows=[];for(const row of e.rows){if(row.key.startsWith('extra:'))continue;const def=defaultLabor(row),custom=c.hours[row.key],current=custom?.signature===row.signature,stale=!!custom&&!current,covered=packageQuoted||row.quote?.scope==='installed';let hours=current?custom.hours:def.hours===null?null:def.hours*c.siteFactor;const stats=market.data[def.trade],override=c.rate?.zip===S.zip?c.rate.value:null,rateLow=c.mode==='diy'?0:override??(stats?stats.low*c.factor:null),rateHigh=c.mode==='diy'?0:override??(stats?stats.high*c.factor:null),amountLow=covered?0:hours===null||rateLow===null?null:hours*rateLow,amountHigh=covered?0:hours===null||rateHigh===null?null:hours*rateHigh;if(!covered){if(amountLow===null)unknown++;else{low+=amountLow;high+=amountHigh;knownHours+=hours}}laborRows.push({...row,hours,trade:def.trade,basis:def.basis,current,stale,covered,rateLow,rateHigh,amountLow,amountHigh})}
const supply=e.rows.filter(r=>!r.key.startsWith('extra:')&&r.quote?.scope!=='installed').reduce((n,r)=>n+(r.amount??0),0),bundled=e.rows.filter(r=>r.quote?.scope==='installed'&&r.key!=='extra:labour').reduce((n,r)=>n+(r.amount??0),0),other=e.subtotal-supply-bundled-(packageQuoted?packageRow.amount:0),reserveRate=S.reserve/100;return {...e,costConflict:packageConflict,unknown:e.unknown-(!packageQuoted&&packageRow?.amount===null?1:0)+(packageConflict?1:0),labor:{rows:laborRows,low,high,knownHours,unknown,market,packageQuoted,packageAmount:packageQuoted?packageRow.amount:0},breakdown:{supply,bundled,other},planningLow:(e.subtotal+low)*(1+reserveRate),planningHigh:(e.subtotal+high)*(1+reserveRate),planningReserveLow:(e.subtotal+low)*reserveRate,planningReserveHigh:(e.subtotal+high)*reserveRate}}
function laborSettingsMarkup(e){const c=S.costSettings,m=e.labor.market,rate=c.rate?.zip===S.zip?c.rate.value:'';return `<details class="labor-settings"><summary>How the labor estimate works <span>${esc(m.name)} | ${REGIONAL_WAGES.dataYear} wage data</span></summary><p>ZIP resolves your state; changing state automatically changes the wage benchmark. These are employee wages, not contractor offers. Template hours and the billing multiplier are editable assumptions.</p><div class="labor-fields"><label>Labor approach<select id="labor-mode"><option value="hire" ${c.mode==='hire'?'selected':''}>Estimate hired labor</option><option value="diy" ${c.mode==='diy'?'selected':''}>DIY for modeled tasks only</option></select></label><label>Wage-to-billing multiplier<input id="labor-factor" type="number" min="1" max="5" step=".1" value="${c.factor}"></label><label>Site time factor<input id="labor-site-factor" type="number" min=".25" max="4" step=".25" value="${c.siteFactor}"></label><label>Your hourly rate for this ZIP<input id="labor-rate" type="number" min="1" max="500" step=".5" placeholder="Use wage benchmark" value="${rate}" ${S.zip?'':'disabled'}></label></div><p class="note">Default multiplier 2× is Terra’s planning assumption for overhead, benefits and margin, not a BLS statistic. Site factor scales template hours; your edited row hours are used as entered. DIY removes modeled labor only; unpriced specialist work remains outside the range.</p><div class="wage-evidence">${['garden','build'].map(k=>{const w=m.data[k];return `<p><strong>${k==='garden'?'Landscaping crew':'Construction laborers'}</strong><br>${w?decimalMoney(w.low)+'–'+decimalMoney(w.high)+'/hour employee wages (25th–75th percentiles)':'Wage estimate unavailable for this state'}</p>`}).join('')}</div><p class="note">Source: <a class="source-link" href="https://www.onetonline.org/link/localwages/37-3011.00?st=${m.state||'NY'}" target="_blank" rel="noopener">O*NET OnLine / BLS OEWS</a>, ${REGIONAL_WAGES.dataYear}; retrieved ${REGIONAL_WAGES.retrieved}. <a class="source-link" href="${REGIONAL_WAGES.license}" target="_blank" rel="noopener">CC BY 4.0</a>. Wage estimates are annual snapshots. Supplier prices and contractor quotes are not a live feed.</p></details>`}
function laborTableMarkup(e){return `<section class="labor-breakdown"><h2>Possible labor cost</h2><p>${e.labor.packageQuoted?'Your whole-project labor quote replaces all computed labor below.':esc(e.labor.market.level)+'. '+e.labor.knownHours.toFixed(1)+' modeled worker-hours. '+e.labor.unknown+' installation scopes still need a quote or your input.'}</p><div class="labor-row labor-heading"><span>Scope / basis</span><span>Worker-hours</span><span>Labor estimate</span></div>${e.labor.rows.map(r=>`<div class="labor-row"><div><strong>${esc(r.name)}</strong><small>${r.covered?'Included in '+(e.labor.packageQuoted?'whole-project labor quote':'supply & installation quote'):r.current?'Your hours for this quantity':esc(r.basis)}</small>${r.stale?'<small class="compatibility-note">Previous hours no longer match this scope. Template hours are shown until you review.</small>':''}</div><div>${r.covered?'<span>Included</span>':`<input class="labor-hours" data-labor-key="${esc(r.key)}" aria-label="Worker hours for ${esc(r.name)}" type="number" min="0" max="10000" step=".25" placeholder="Set hours" value="${r.hours===null?'':Number(r.hours.toFixed(2))}">${r.current?`<button class="text-btn" data-reset-hours="${esc(r.key)}">Use template</button>`:''}`}</div><strong>${r.covered?'Included':r.amountLow===null?'Quote / input needed':costRange(r.amountLow,r.amountHigh)}</strong></div>`).join('')}<div class="labor-row labor-total"><strong>${e.labor.packageQuoted?'Recorded labor package':'Modeled labor subtotal'}</strong><span>${e.labor.knownHours.toFixed(1)} h</span><strong>${e.labor.packageQuoted?money(e.labor.packageAmount):costRange(e.labor.low,e.labor.high)}</strong></div><p class="note">Hours are worker-hours, not a promised duration or crew schedule. Lighting, utilities, structural work and other specialist scopes stay unestimated unless you enter their hours or record a quote. Quantity changes invalidate custom hours. Installed quotes are counted once.</p></section>`}
function budgetView(){const settingsOpen=$('.labor-settings')?.open;budgetSourceView();const e=estimate();$('#pricing-total').textContent=costRange(e.planningLow,e.planningHigh);$('.estimate-banner .eyebrow').textContent='Materials + possible labor + reserve | incomplete plan';$('.estimate-banner p').textContent=(S.zip?'ZIP '+S.zip+' | '+e.labor.market.name+'. ':'US baseline; add your ZIP. ')+e.unknown+' supply / site scopes and '+e.labor.unknown+' labor scopes remain unpriced. Figures update with your design and assumptions.';const split=$('#budget-table .price-split');split.outerHTML=`<div class="cost-split"><div><span>Materials / supply</span><strong>${money(e.breakdown.supply)}</strong></div><div><span>Supply + install bundles</span><strong>${money(e.breakdown.bundled)}</strong></div><div><span>${e.labor.packageQuoted?'Quoted labor':'Possible labor'}</span><strong>${e.labor.packageQuoted?money(e.labor.packageAmount):costRange(e.labor.low,e.labor.high)}</strong></div><div><span>Other recorded costs</span><strong>${money(e.breakdown.other)}</strong></div></div><p class="cost-source-note">Supply lines below identify sample allowances and ZIP-matched quotes. Bundled quotes do not separate materials from labor. Unknown costs are excluded, never treated as zero.</p>${e.costConflict?'<p class="compatibility-note">Your whole-project labor quote overlaps installed bundles and is excluded from this range. Use supply-only quotes or remove the overlapping labor package.</p>':''}${laborSettingsMarkup(e)}`;$('#budget-table').insertAdjacentHTML('beforeend',laborTableMarkup(e)+`<div class="planning-total"><span>Combined reserve (${S.reserve}%)</span><strong>${costRange(e.planningReserveLow,e.planningReserveHigh)}</strong><span>Known / modeled planning range</span><strong>${costRange(e.planningLow,e.planningHigh)}</strong></div>`);const legacyTotal=$('#budget-table .price-row.total>span');if(legacyTotal)legacyTotal.textContent='Priced supply / quotes + reserve';$('#budget-advice').innerHTML=`<div class="advice">${e.planningLow>S.target?'The modeled portion starts '+money(e.planningLow-S.target)+' above your target.':e.planningHigh>S.target?'The modeled range crosses your target by up to '+money(e.planningHigh-S.target)+'.':'Up to '+money(S.target-e.planningHigh)+' of your target remains after the modeled high estimate.'} Unpriced scopes are additional. This range is not a contractor offer.</div>`;bindLaborFields(e);if(settingsOpen)$('.labor-settings').open=true}
function bindLaborFields(e){const c=S.costSettings;$('#labor-mode').onchange=event=>change(()=>c.mode=event.target.value);for(const [id,key,min,max] of [['labor-factor','factor',1,5],['labor-site-factor','siteFactor',.25,4]])$('#'+id).onchange=event=>{const v=+event.target.value;if(Number.isFinite(v)&&v>=min&&v<=max)change(()=>c[key]=v);else renderPricing()};$('#labor-rate').onchange=event=>{const raw=event.target.value.trim(),v=+raw;if(!raw)change(()=>c.rate=null);else if(S.zip&&v>0&&v<=500)change(()=>c.rate={zip:S.zip,value:v});else renderPricing()};$$('[data-labor-key]').forEach(input=>input.onchange=()=>{const row=e.rows.find(r=>r.key===input.dataset.laborKey),v=+input.value;if(input.value.trim()===''){change(()=>delete c.hours[row.key]);return}if(row&&Number.isFinite(v)&&v>=0&&v<=10000)change(()=>c.hours[row.key]={signature:row.signature,hours:v});else renderPricing()});$$('[data-reset-hours]').forEach(b=>b.onclick=()=>change(()=>delete c.hours[b.dataset.resetHours]))}
function bindLocationFields(){$$('.zip-fields').forEach(box=>{const input=box.querySelector('.zip-input'),button=box.querySelector('.zip-lookup');button.onclick=()=>lookupZip(input.value);input.oninput=()=>{clearTimeout(zipInputTimer);const value=input.value.trim();if(/^\d{5}$/.test(value))zipInputTimer=setTimeout(()=>{if(value!==S.zip||!S.location)lookupZip(value)},550)};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();clearTimeout(zipInputTimer);lookupZip(input.value)}}})}
