function sceneEntries(){return [...S.items.map(i=>({type:'item',id:i.id,name:CATALOG[i.kind].name,group:CATALOG[i.kind].type==='plant'?'plants':CATALOG[i.kind].type==='light'?'lights':'objects',thumb:catalogThumb(i.kind),detail:i.w+' × '+i.h+' ft'})),...S.routes.map(r=>({type:'route',id:r.id,name:UTILITY_TYPES[r.kind]?.name||'Service route',group:'services',detail:pathLength(r).toFixed(1)+' ft | '+(ROUTE_STATES[r.status]||'Unverified')})),...S.strings.map(s=>({type:'string',id:s.id,name:s.name,group:'lights',detail:pathLength(s).toFixed(1)+' ft span'})),...S.paths.map(p=>({type:'path',id:p.id,name:p.name,group:'ground',detail:pathLength(p).toFixed(1)+' ft route'})),...S.zones.map(z=>({type:'zone',id:z.id,name:z.name,group:'ground',detail:'Planting area'}))]}
