function refreshSelectionTools(){const bar=$('#selection-tools');if(!bar)return;const hit=selectedRecord();bar.innerHTML=tool!=='select'?`<span><strong>${{soil:'Planting bed',route:'Service route',path:'Walkway',string:'Light strand'}[tool]||'Drawing'}</strong> | ${draft.length} points</span><button id="canvas-finish" class="outline-btn" ${draft.length<(tool==='soil'?3:2)?'disabled':''}>Finish drawing</button><button id="canvas-cancel" class="text-btn">Cancel</button>`:hit?`<span><strong>${esc(hit.name)}</strong><small>Selected | Delete / Backspace removes; Ctrl / Cmd + Z restores</small></span><button id="inspect-selection" class="text-btn">Details</button><button id="remove-selection" class="outline-btn">Remove</button>`:'<span>Select a piece on the canvas or in the object list. Drag to move it.</span><a class="text-btn" href="#visuals">Present your garden</a>';if($('#remove-selection'))$('#remove-selection').onclick=removeSelection;if($('#inspect-selection'))$('#inspect-selection').onclick=()=>{$('.inspector').scrollIntoView({block:'nearest',behavior:'smooth'});$('.inspector').focus({preventScroll:true})};if($('#canvas-finish'))$('#canvas-finish').onclick=finishDraw;if($('#canvas-cancel'))$('#canvas-cancel').onclick=()=>{draft=[];tool='select';renderAll(true)};const e=estimate();$('#studio-cost').textContent=costRange(e.planningLow,e.planningHigh);$('#scene-count').textContent=sceneEntries().length+' elements';refreshSceneList()}
function refreshSceneList(){const host=$('#scene-list');if(!host)return;const entries=sceneEntries().filter(e=>trayFilter==='all'||e.group===trayFilter);host.innerHTML=entries.length?entries.map(i=>`<button class="scene-entry ${selection?.type===i.type&&selection.id===i.id?'selected':''}" data-scene-type="${i.type}" data-scene-id="${esc(i.id)}">${i.thumb||`<span class="scene-type">${esc(i.type==='route'?'Service':i.type)}</span>`}<span>${esc(i.name)}<small>${esc(i.detail)}</small></span></button>`).join(''):'<p class="note">No elements in this category yet. Add pieces or draw a route.</p>';$$('[data-scene-id]').forEach(b=>b.onclick=()=>selectScene(b.dataset.sceneType,b.dataset.sceneId));$$('[data-tray-filter]').forEach(b=>{b.classList.toggle('active',trayFilter===b.dataset.trayFilter);b.onclick=()=>{trayFilter=b.dataset.trayFilter;refreshSceneList()}})}
function bindExperience(){document.addEventListener('keydown',event=>{const el=event.target;if(el.isContentEditable||el.closest?.('input,textarea,select,[contenteditable=true],[role=textbox]')||document.querySelector('dialog[open]')||location.hash!=='#studio')return;if((event.metaKey||event.ctrlKey)&&!event.altKey){if(event.key.toLowerCase()==='z'){event.preventDefault();$(event.shiftKey?'#redo':'#undo').click()}else if(event.key.toLowerCase()==='y'){event.preventDefault();$('#redo').click()}return}if(event.key==='Escape'&&tool!=='select'){event.preventDefault();tool='select';draft=[];renderAll(true);return}if(event.key==='Enter'&&tool!=='select'){event.preventDefault();finishDraw();return}if((event.key==='Delete'||event.key==='Backspace')&&!event.repeat&&tool==='select'&&!event.altKey&&removeSelection())event.preventDefault()});$('#presentation-garden').onclick=()=>{sceneMode='garden';renderPerspective()};$('#presentation-technical').onclick=()=>{sceneMode='technical';renderPerspective()};$('#download-presentation').onclick=()=>download(presentationSvg(),'terra-presentation-v'+S.version+'.svg','image/svg+xml');$('#print-presentation').onclick=()=>window.print()}
function renderShowcase(){const original={layers:S.layers,view:S.view,labels:S.labels};try{if(sceneMode==='garden'){S.layers={ground:true,above:true,underground:false};S.view='composite';S.labels=false}renderLayerPerspective()}finally{Object.assign(S,original)}$('#preview-layer').disabled=sceneMode==='garden';$('#presentation-garden').classList.toggle('active',sceneMode==='garden');$('#presentation-technical').classList.toggle('active',sceneMode==='technical');$('.render-label').textContent=sceneMode==='garden'?'Garden concept | illustrated view':'Technical concept | current layers';$('#render-status').textContent='Garden V'+S.version+' | '+(sceneMode==='garden'?'Presentation':'Technical layers');renderPresentationBoard()}
