function renderPresentationBoard(){const board=$('#presentation-board');if(!board)return;const e=estimate(),plants=S.items.filter(i=>CATALOG[i.kind].type==='plant'),materials=[...new Set([S.material,...S.paths.map(p=>p.material)])],place=S.location?.zip===S.zip?S.location.city+', '+S.location.state+' | '+S.zip:S.zip?'ZIP '+S.zip:'Location not set';$('#presentation-name').textContent=S.name;$('#presentation-meta').textContent=S.width+' × '+S.depth+' ft | '+Math.round(e.area)+' sq ft | '+place;$('#presentation-plan').src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 850 620">'+planSnapshot()+'</svg>');$('#presentation-palette').innerHTML=materials.map(k=>`<div>${materialSwatch(k,'showcase')}<span>${esc(MATERIALS[k].name)}</span></div>`).join('');$('#presentation-planting').textContent=plants.length?plants.map(i=>CATALOG[i.kind].name).filter((n,i,a)=>a.indexOf(n)===i).join(', '):'No planting symbols placed yet.';$('#presentation-cost').textContent=costRange(e.planningLow,e.planningHigh);$('#presentation-cost-note').textContent='Materials, possible labor and '+S.reserve+'% reserve. Incomplete: '+e.unknown+' supply/site scopes and '+e.labor.unknown+' labor scopes unpriced. Illustrated concept, not a photograph or construction drawing.'}
function presentationSvg(){const e=estimate(),plan=planSnapshot(),scene=$('#perspective').innerHTML,title=esc(S.name),palette=[...new Set([S.material,...S.paths.map(p=>p.material)])];return `<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="1120" viewBox="0 0 1440 1120"><metadata>Employee wage benchmarks: U.S. Department of Labor, O*NET OnLine, BLS OEWS 2025; https://www.onetonline.org/link/localwages/37-3011.00 and https://www.onetonline.org/link/localwages/47-2061.00 ; CC BY 4.0 https://creativecommons.org/licenses/by/4.0/ . Planning costs derived with editable hours and billing assumptions.</metadata><rect width="1440" height="1120" fill="#fbfcf8"/><text x="48" y="60" font-family="Georgia" font-size="34" fill="#294331">${title}</text><text x="48" y="93" font-family="Arial" font-size="16" fill="#52614d">${S.width} × ${S.depth} ft | ${Math.round(e.area)} sq ft | ${esc(S.zip?'ZIP '+S.zip:'Location not set')} | Garden V${S.version}</text><svg x="24" y="120" width="960" height="700" viewBox="0 0 1000 720">${scene}</svg><svg x="1000" y="160" width="400" height="320" viewBox="0 0 850 620">${namespaceResources(plan,'board-')}</svg><text x="1010" y="140" font-family="Arial" font-size="18" fill="#294331">Garden plan</text><text x="48" y="866" font-family="Arial" font-size="18" fill="#294331">Material palette</text>${palette.slice(0,7).map((k,i)=>`<svg x="${48+i*185}" y="886" width="160" height="84" viewBox="0 0 80 60"><defs>${materialTexture(k,'board-swatch-'+k)}</defs><rect width="80" height="60" fill="url(#board-swatch-${k})"/></svg><text x="${48+i*185}" y="992" font-family="Arial" font-size="12" fill="#294331">${esc(MATERIALS[k].name.slice(0,27))}</text>`).join('')}<text x="48" y="1040" font-family="Arial" font-size="20" fill="#294331">Planning range: ${esc(costRange(e.planningLow,e.planningHigh))} | materials + possible labor + ${S.reserve}% reserve</text><text x="48" y="1074" font-family="Arial" font-size="13" fill="#52614d">Incomplete estimate; unpriced scopes are additional. ${REGIONAL_WAGES.dataYear} BLS employee wages via O*NET, plus editable planning assumptions.</text><text x="48" y="1100" font-family="Arial" font-size="13" fill="#52614d">Illustrated garden concept. No live supplier price feed. Not a photograph or construction specification.</text></svg>`}

